'use strict';
let layerReorderDrag=null,layerReorderTimer=null;
function reorderLayer(id,targetId,before){if(id===targetId)return false;const item=layers.find(l=>l.id===id),target=layers.find(l=>l.id===targetId);if(!item||!target)return false;const next=layers.filter(l=>l.id!==id),index=next.indexOf(target)+(before?1:0);next.splice(index,0,item);if(next.every((l,i)=>l===layers[i]))return false;checkpoint();layers=next;selectLayer(id);ui();return true}
function clearReorderMarks(){for(const row of $('layers').children)row.classList.remove('reordering','drop-before','drop-after')}
function endLayerReorder(apply=false){clearTimeout(layerReorderTimer);const d=layerReorderDrag;layerReorderDrag=null;clearReorderMarks();if(apply&&d?.target!=null)reorderLayer(d.id,d.target,d.before)}
function attachLayerReorder(row,layer){const handle=document.createElement('button');handle.textContent='↕';handle.className='layer-order-handle';handle.setAttribute('aria-label','Изменить порядок: '+layer.name);handle.dataset.tooltip='Потяните вверх или вниз, чтобы изменить порядок наложения. Стрелки ↑ и ↓ также работают. Для дальних объектов прокрутите список.';handle.onclick=e=>e.stopPropagation();handle.onpointerdown=e=>{if(e.button!=null&&e.button!==0)return;e.preventDefault();e.stopPropagation();endLayerReorder();layerReorderDrag={id:layer.id,pointer:e.pointerId,target:null,pager:null};row.classList.add('reordering');handle.setPointerCapture(e.pointerId)};
 handle.onpointermove=e=>{const d=layerReorderDrag;if(!d||d.pointer!==e.pointerId)return;e.preventDefault();e.stopPropagation();const el=document.elementFromPoint(e.clientX,e.clientY),pager=el?.closest('#prevLayers,#nextLayers');if(pager&&!pager.disabled){if(d.pager!==pager){clearTimeout(layerReorderTimer);d.pager=pager;layerReorderTimer=setTimeout(()=>{if(layerReorderDrag===d){pager.click();d.pager=null}},550)}return}clearTimeout(layerReorderTimer);d.pager=null;clearReorderMarks();row.classList.add('reordering');const target=el?.closest('.layer[data-layer-id]');d.target=target?Number(target.dataset.layerId):null;if(d.target==null||d.target===d.id)return;const r=target.getBoundingClientRect();d.before=e.clientY<r.top+r.height/2;target.classList.add(d.before?'drop-before':'drop-after')};
 handle.onpointerup=e=>{if(layerReorderDrag?.pointer!==e.pointerId)return;e.stopPropagation();endLayerReorder(true)};handle.onpointercancel=()=>endLayerReorder();handle.onlostpointercapture=()=>endLayerReorder();handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopPropagation();const index=layers.findIndex(l=>l.id===layer.id),other=layers[index+(e.key==='ArrowUp'?1:-1)];if(other){reorderLayer(layer.id,other.id,e.key==='ArrowUp');$('layers').querySelector(`[data-layer-id="${layer.id}"] .layer-order-handle`)?.focus()}};row.append(handle)}
ui();
